"use client";

import { type KeyboardEvent, useId, useRef, useState } from "react";

import {
  CalendarIcon,
  SparklesIcon,
  UsersIcon,
} from "@/components/blocks/parts/icons";
import { Switch } from "@/components/motion/switch";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { BlockFrame } from "../parts/block-frame";
import { DemoScene } from "./ai-feature-launch/demo-scene";
import { useLoopClock } from "./ai-feature-launch/use-loop-clock";
import { ClockIcon } from "./icons";
import type { VarStyle } from "@/components/blocks/lib/css-vars";

const STEPS = [
  {
    title: "Spots the gap",
    text: "A patient cancels and the slot shows up free on the calendar.",
  },
  {
    title: "Asks the waitlist",
    text: "Fernhill texts the patients who asked for an earlier visit.",
  },
  {
    title: "Fills the slot",
    text: "The first patient to reply gets it. Nobody rings round.",
  },
];

const BENEFITS = [
  { icon: CalendarIcon, text: "Rooms stay booked after late cancellations" },
  { icon: UsersIcon, text: "Patients on the waitlist are seen sooner" },
  { icon: ClockIcon, text: "The front desk keeps its morning" },
];

const STEP_MS = 4200;

/**
 * An in-product launch card for a new assistant feature. A looping demo,
 * its step dots and the autoplay all run off one clock that pauses off
 * screen. Arrows on the dots change the step and stop the autoplay.
 */
export function AiFeatureLaunch({ className }: { className?: string }) {
  const frameRef = useRef<HTMLDivElement>(null);
  const clock = useLoopClock(frameRef, STEPS.length, STEP_MS);
  const [enabled, setEnabled] = useState(false);
  const [note, setNote] = useState("");
  const titleId = useId();
  const switchId = useId();
  const tabsId = useId();
  const tabRefs = useRef<(HTMLButtonElement | null)[]>([]);

  const move = (next: number) => {
    const step = (next + STEPS.length) % STEPS.length;
    clock.goTo(step);
    tabRefs.current[step]?.focus();
  };

  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    let next: number;
    if (event.key === "ArrowRight") next = clock.step + 1;
    else if (event.key === "ArrowLeft") next = clock.step - 1;
    else if (event.key === "Home") next = 0;
    else if (event.key === "End") next = STEPS.length - 1;
    else return;
    event.preventDefault();
    move(next);
  };

  return (
    <BlockFrame aria-labelledby={titleId} className={cn("max-w-md", className)}>
      <div ref={frameRef} className="flex flex-col gap-5 p-5">
        <DemoScene step={clock.step} progress={clock.progress} />

        <div
          role="tablist"
          aria-label="Tour steps"
          onKeyDown={onKeyDown}
          className="flex items-center gap-1"
        >
          {STEPS.map((step, index) => {
            const selected = index === clock.step;
            const past = index < clock.step;
            return (
              <Button
                key={step.title}
                ref={(node) => {
                  tabRefs.current[index] = node;
                }}
                id={`${tabsId}-tab-${index}`}
                role="tab"
                variant="ghost"
                size="sm"
                aria-selected={selected}
                aria-controls={`${tabsId}-panel`}
                aria-label={`Step ${index + 1} of ${STEPS.length}: ${step.title}`}
                tabIndex={selected ? 0 : -1}
                onClick={() => move(index)}
              >
                <span className="flex h-6 items-center px-1">
                  <span
                    aria-hidden="true"
                    className={cn(
                      "relative block h-1.5 overflow-hidden rounded-full bg-muted motion-safe:transition-all motion-safe:duration-300",
                      selected ? "w-8" : "w-1.5",
                      past ? "bg-chart-1/50" : undefined,
                    )}
                  >
                    {selected ? (
                      <span
                        className="absolute inset-y-0 left-0 w-(--w) rounded-full bg-chart-1"
                        style={
                          // SAFETY: the object holds only CSS custom properties, which CSSProperties does not list.
                          { "--w": `${clock.progress * 100}%` } as VarStyle
                        }
                      />
                    ) : null}
                  </span>
                </span>
              </Button>
            );
          })}
          <span className="ml-auto text-xs text-muted-foreground tabular-nums">
            {clock.step + 1} of {STEPS.length}
          </span>
        </div>

        <div
          id={`${tabsId}-panel`}
          role="tabpanel"
          aria-labelledby={`${tabsId}-tab-${clock.step}`}
          className="grid"
        >
          {STEPS.map((step, index) => (
            <div
              key={step.title}
              aria-hidden={index !== clock.step}
              className={cn(
                "col-start-1 row-start-1 flex flex-col gap-1 motion-safe:transition-all motion-safe:duration-300",
                index === clock.step
                  ? "translate-y-0 opacity-100"
                  : "pointer-events-none translate-y-1 opacity-0",
              )}
            >
              <h3 className="flex items-center gap-2 text-sm font-medium text-muted-foreground">
                <SparklesIcon
                  aria-hidden="true"
                  className="size-4 text-chart-4"
                />
                {step.title}
              </h3>
              <p className="text-sm">{step.text}</p>
            </div>
          ))}
        </div>

        <div className="flex flex-col gap-1">
          <h2
            id={titleId}
            className="text-xl font-semibold tracking-tight text-balance"
          >
            Fill cancelled slots without a phone call
          </h2>
          <p className="text-sm text-muted-foreground">
            Gap filler offers every freed slot to your waitlist, then books the
            first yes.
          </p>
        </div>

        <ul className="flex flex-col gap-2.5">
          {BENEFITS.map(({ icon: Icon, text }, index) => (
            <li key={text} className="flex items-center gap-3 text-sm">
              <span
                aria-hidden="true"
                className={cn(
                  "flex size-7 shrink-0 items-center justify-center rounded-lg",
                  [
                    "bg-marketing-blue-surface text-marketing-blue-ink",
                    "bg-marketing-green-surface text-marketing-green-ink",
                    "bg-marketing-purple-surface text-marketing-purple-ink",
                  ][index],
                )}
              >
                <Icon className="size-4" />
              </span>
              {text}
            </li>
          ))}
        </ul>

        <div className="flex items-center justify-between gap-4 rounded-xl border border-border px-4 py-3">
          <label
            htmlFor={switchId}
            className="flex min-w-0 cursor-pointer flex-col"
          >
            <span className="text-sm font-medium">
              Turn on for my workspace
            </span>
            <span className="text-xs text-muted-foreground">
              Only admins see this switch
            </span>
          </label>
          <Switch
            id={switchId}
            checked={enabled}
            onCheckedChange={setEnabled}
          />
        </div>

        <div className="flex flex-wrap items-center justify-end gap-2">
          <p role="status" className="mr-auto text-xs text-muted-foreground">
            {note || (enabled ? "On for all four clinics" : "")}
          </p>
          <Button
            variant="outline"
            onClick={() => setNote("The Gap filler guide opened in a new tab")}
          >
            Learn more
          </Button>
          <Button
            onClick={() => setNote("A sample cancellation is on your calendar")}
          >
            Try it now
          </Button>
        </div>
      </div>
    </BlockFrame>
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

import { cn } from "@/lib/utils";

import { FALLBACK_GLYPHS } from "./glyphs";
import type { BlockIconGlyphs, BlockIconName } from "./icon-names";

export type { BlockIconGlyphs, BlockIconName } from "./icon-names";

const GlyphContext = createContext<BlockIconGlyphs>(FALLBACK_GLYPHS);

/**
 * Hands the blocks under it the icons of one open-source pack. With no
 * provider, a block draws the glyphs in `./glyphs`: none on this site, which
 * always supplies a pack, and one open-source pack in an installed copy.
 */
export function BlockIconProvider({ glyphs, children }: { glyphs: BlockIconGlyphs; children: ReactNode }) {
  return <GlyphContext.Provider value={glyphs}>{children}</GlyphContext.Provider>;
}

/**
 * Makes an icon drawn from the chosen pack. Every name in `BLOCK_ICON_NAMES` is available. `turn` rotates the pack's glyph when the
 * pack has only one direction of it, such as an up arrow.
 */
export function packIcon(name: BlockIconName, turn?: string) {
  return function BlockIcon({ className, ...props }: SVGProps<SVGSVGElement>) {
    const glyph = useContext(GlyphContext)[name];
    return glyph ? <svg {...glyph} {...props} className={cn(turn, className)} /> : null;
  };
}

/** An icon no pack supplies, drawn here as plain strokes in the current colour. */
export function ownIcon(paths: ReactNode) {
  return function BlockIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        aria-hidden="true"
        focusable="false"
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        {...props}
      >
        {paths}
      </svg>
    );
  };
}

