import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

import { CheckIcon } from "@/components/blocks/parts/icons";
import { cn } from "@/lib/utils";

/** Props for the looping demo drawing. */
export interface DemoSceneProps {
  /** The tour step, which sets what the drawing shows. */
  step: number;
  /** How far through the step, from 0 to 1. The replies arrive along it. */
  progress: number;
}

const ROOMS = ["Room 1", "Room 2", "Room 3"];
const TIMES = ["9:00", "10:00", "11:00"];
// Which slots are booked in the drawing, room by time. The middle slot of room 2 is the one that frees up.
const BOOKED = [
  [true, true, false],
  [true, true, true],
  [false, true, true],
];
const WAITLIST = [
  {
    name: "Jonah P.",
    tint: "bg-marketing-blue-surface text-marketing-blue-ink",
  },
  {
    name: "Ines D.",
    tint: "bg-marketing-purple-surface text-marketing-purple-ink",
  },
  {
    name: "Ravi K.",
    tint: "bg-marketing-pink-surface text-marketing-pink-ink",
  },
];

/**
 * A small drawing of one clinic morning: three rooms by three hours. A visit
 * is cancelled, the waitlist is asked, then the first reply fills the slot.
 * It is decorative; the step text says the same in words.
 */
export function DemoScene({ step, progress }: DemoSceneProps) {
  const asked = step >= 1;
  const filled = step === 2;
  const replies =
    step === 1
      ? Math.min(WAITLIST.length, Math.floor(progress * 4))
      : step === 2
        ? WAITLIST.length
        : 0;

  return (
    <div
      aria-hidden="true"
      className="grid grid-cols-[1fr_auto] gap-4 rounded-xl border border-border bg-background p-4"
    >
      <div className="grid grid-cols-[2.5rem_repeat(3,1fr)] gap-1.5 text-xs text-muted-foreground">
        <span />
        {ROOMS.map((room) => (
          <span key={room} className="truncate text-center">
            {room}
          </span>
        ))}
        {TIMES.map((time, row) => (
          <div key={time} className="contents">
            <span className="self-center tabular-nums">{time}</span>
            {ROOMS.map((room, column) => {
              const target = column === 1 && row === 1;
              const booked = BOOKED[column]?.[row] ?? false;
              return (
                <span
                  key={room}
                  className={cn(
                    "flex h-7 items-center justify-center rounded-md motion-safe:transition-colors motion-safe:duration-300",
                    target
                      ? filled
                        ? "bg-marketing-green-surface text-marketing-green-ink"
                        : "border border-dashed border-chart-3 bg-marketing-orange-surface text-marketing-orange-ink"
                      : booked
                        ? "bg-chart-1/20"
                        : "bg-muted",
                  )}
                >
                  {target ? (
                    filled ? (
                      <CheckIcon className="size-3.5" />
                    ) : (
                      <span className="font-medium">Free</span>
                    )
                  ) : null}
                </span>
              );
            })}
          </div>
        ))}
      </div>
      <ul className="flex w-24 flex-col justify-center gap-1.5">
        {WAITLIST.map((person, index) => {
          const replied = index < replies;
          const winner = filled && index === 0;
          return (
            <li
              key={person.name}
              className={cn(
                "flex items-center gap-1.5 rounded-full py-0.5 pr-2 pl-0.5 text-xs motion-safe:transition-all motion-safe:duration-300",
                asked ? "translate-y-0 opacity-100" : "translate-y-1 opacity-0",
                winner
                  ? "bg-marketing-green-surface text-marketing-green-ink"
                  : "bg-muted",
                filled && !winner ? "opacity-50" : undefined,
              )}
            >
              <span
                className={cn(
                  "flex size-5 items-center justify-center rounded-full font-semibold",
                  person.tint,
                )}
              >
                {person.name[0]}
              </span>
              <span className="truncate">
                {replied ? (index === 0 ? "Yes!" : "Me too") : "..."}
              </span>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

"use client";

import { useReducedMotion } from "motion/react";
import {
  type RefObject,
  useCallback,
  useEffect,
  useRef,
  useState,
} from "react";

/** One shared clock for a looping tour: the step, how far through it, and the controls. */
export interface LoopClock {
  step: number;
  /** How far through the current step, from 0 to 1. */
  progress: number;
  /** Whether the tour moves on by itself. */
  autoplay: boolean;
  /** Jumps to a step and stops the autoplay, because the person took over. */
  goTo: (step: number) => void;
}

const FRAME_MS = 50;

/**
 * Drives the demo, the dot fill and the autoplay from one clock, so they never
 * drift apart. The clock pauses while the card is off screen or the tab is
 * hidden, and never starts for a person who asks for reduced motion. Its
 * interval is cleared whenever it pauses and on unmount.
 */
export function useLoopClock(
  target: RefObject<HTMLElement | null>,
  steps: number,
  stepMs: number,
): LoopClock {
  const reduceMotion = useReducedMotion();
  const [elapsed, setElapsed] = useState(0);
  const [autoplay, setAutoplay] = useState(true);
  const [visible, setVisible] = useState(false);
  const elapsedRef = useRef(0);
  const cycle = steps * stepMs;

  useEffect(() => {
    const node = target.current;
    if (!node) return;
    const observer = new IntersectionObserver(
      ([entry]) => setVisible(entry?.isIntersecting ?? false),
      { threshold: 0.25 },
    );
    observer.observe(node);
    return () => observer.disconnect();
  }, [target]);

  const playing = autoplay && visible && !reduceMotion;

  useEffect(() => {
    if (!playing) return;
    const id = window.setInterval(() => {
      if (document.hidden) return;
      elapsedRef.current = (elapsedRef.current + FRAME_MS) % cycle;
      setElapsed(elapsedRef.current);
    }, FRAME_MS);
    return () => window.clearInterval(id);
  }, [playing, cycle]);

  const goTo = useCallback(
    (step: number) => {
      elapsedRef.current = (((step % steps) + steps) % steps) * stepMs;
      setElapsed(elapsedRef.current);
      setAutoplay(false);
    },
    [steps, stepMs],
  );

  const step = Math.floor(elapsed / stepMs) % steps;
  return {
    step,
    progress: playing ? (elapsed % stepMs) / stepMs : 1,
    autoplay: playing,
    goTo,
  };
}

